// ===== DEBOUNCE CANH BAO TE NGA TU CAMERA AI =====
var lastAlertTime = global.get('fallLastAlertTime') || 0;
var now = Date.now();
var COOLDOWN = 60 * 1000; // 60 giay

if (lastAlertTime !== 0 && (now - lastAlertTime) < COOLDOWN) {
    return null; // dang cooldown, tranh gui lap canh bao
}

global.set('fallLastAlertTime', now);

msg.topic = "fall";
msg.eventTime = new Date().toISOString();

// Camera AI gui image_path cua anh hien truong.
// Neu khong doc duoc anh, node Telegram phia sau se gui canh bao dang text.
if (msg.payload && msg.payload.image_path) {
    msg.filename = msg.payload.image_path;
} else {
    msg.filename = "/opt/smart-home/assets/fallback_fall.jpg"; // placeholder, it dung toi
}

// Firmware ESP32 hien da subscribe home/esp32/alarm.
// FALL_ALARM_ON se bat coi canh bao te nga 1000 Hz.
msg.payload = "FALL_ALARM_ON";
return msg;

if (msg.error) {
    // Khong doc duoc anh (AI chua kip luu file, ESP32 PIR khong co anh, sai duong dan...)
    msg.payload = {
        chatId: "8823676499",
        type: "message",
        content: "CANH BAO TE NGA KHAN CAP! (Khong lay duoc anh hien truong)"
    };
} else {
    var imageBuffer = msg.payload;
    msg.payload = {
        chatId: "8823676499",
        type: "photo",
        content: imageBuffer,
        caption: "CANH BAO TE NGA KHAN CAP!"
    };
}
return msg;

// ESP32 (Khang) gui gop tren 1 topic: home/{room}/telemetry, payload:
// { deviceId, room, sensorType, value, unit, alert, timestamp(millis noi bo) }
// Backend (Dong) lai doc topic dang: home/{room}/sensor/{sensorType}
// -> node nay lam cau noi, dong thoi tu tao timestamp that (server-side) vi
// timestamp cua ESP32 la millis() ke tu luc boot, khong dung de luu Mongo (Date).
var data = msg.payload || {};
var room = data.room;
var sensorType = data.sensorType;
if (!room || !sensorType) { return null; }

return {
    topic: "home/" + room + "/sensor/" + sensorType,
    payload: {
        value: data.value,
        unit: data.unit,
        // Firmware ESP32 hien CHUA co truong deviceId rieng (Telemetry.js dang required).
        // Tam gan gia tri mac dinh - de nghi Khang bo sung ID that (vd theo MAC) trong firmware.
        deviceId: data.deviceId || ("esp32-" + room),
        timestamp: new Date().toISOString()
    }
};

// MQ-2 gui gia tri ADC tho trong telemetry.
// Firmware tu bat coi cuc bo khi ADC > 2200; Node-RED tao Telegram va Incident.
var data = msg.payload || {};
if (data.sensorType !== "gas") { return null; }

var GAS_THRESHOLD = 2200; // nguong ADC tho, phai khop firmware ESP32
if (data.value === undefined || data.value === null || data.value <= GAS_THRESHOLD) { return null; }

if (typeof global.gasLastAlertTime === 'undefined') { global.gasLastAlertTime = 0; }
var now = Date.now();
var COOLDOWN = 60 * 1000;
if (global.gasLastAlertTime !== 0 && (now - global.gasLastAlertTime) < COOLDOWN) {
    return null; // dang cooldown
}
global.gasLastAlertTime = now;

var room = data.room || "kitchen";
var eventTime = new Date().toISOString();

var telegramMsg = {
    payload: {
        chatId: "8823676499",
        type: "message",
        content: "🚨 CẢNH BÁO KHẨN CẤP: Phát hiện rò rỉ khí gas tại " + room +
                 " (giá trị: " + data.value + "). Lúc " + new Date().toLocaleTimeString('vi-VN')
    }
};

var backendMsg = {
    topic: "home/" + room + "/alert/gas",
    payload: {
        room: room,
        type: "gas",
        deviceId: data.deviceId || ("esp32-" + room),
        detected: true,
        severity: "critical",
        timestamp: eventTime
    }
};

// Khong gui GAS_ALARM_ON nguoc lai ESP32.
// Firmware da tu dieu khien coi theo gas local va tu tat khi an toan.
return [telegramMsg, backendMsg];

// ESP32 gui temperature va humidity la 2 message RIENG BIET (khac ban cu gop 1 message)
// va co 2 cam bien DHT o 2 phong (livingroom, kitchen) -> can cooldown theo TUNG phong.
var data = msg.payload || {};
if (data.sensorType !== "temperature" && data.sensorType !== "humidity") { return null; }

var room = data.room || "unknown";
var value = data.value;

var TEMP_FIRE = 40;  // KHOP nguong "canh_bao_chay" trong khang/src/main.cpp (coi da tu hu)
var TEMP_HIGH = 35;
var TEMP_LOW = 16;
var HUMID_HIGH = 85;

var alert = null;
if (data.sensorType === "temperature") {
    if (value >= TEMP_FIRE) {
        alert = "🔥 NGUY CƠ QUÁ NHIỆT tại " + room + ": " + value + "°C. Còi vật lý đã tự kích hoạt, kiểm tra ngay!";
    } else if (value >= TEMP_HIGH) {
        alert = "⚠️ Nhiệt độ " + room + " quá cao: " + value + "°C. Kiểm tra điều hòa/quạt cho người già.";
    } else if (value <= TEMP_LOW) {
        alert = "⚠️ Nhiệt độ " + room + " quá thấp: " + value + "°C. Cần giữ ấm cho người già.";
    }
} else if (data.sensorType === "humidity") {
    if (value >= HUMID_HIGH) {
        alert = "⚠️ Độ ẩm " + room + " cao bất thường: " + value + "%.";
    }
}

if (!alert) { return null; }

var key = "dhtLastAlertTime_" + room;
var last = global.get(key) || 0;
var now = Date.now();
var COOLDOWN = 60 * 1000;
if (last !== 0 && (now - last) < COOLDOWN) { return null; }
global.set(key, now);

// Ghi chu: chi gui Telegram, KHONG tao Incident tren Backend, vi contract hien tai giua
// Backend (Dong) va Frontend (Thanh) chi ho tro Incident.type la 'fall' | 'gas' (xem types.ts).
return {
    payload: {
        chatId: "8823676499",
        type: "message",
        content: alert
    }
};

var lastAlertTime = global.get('fallLastAlertTime') || 0;
var now = Date.now();

if (lastAlertTime === 0 || (now - lastAlertTime) > 5 * 60 * 1000) {
    return null;
}

global.set('fallLastAlertTime', 0);

var alarmMsg = { topic: "home/esp32/alarm", payload: "ALARM_OFF" };
var telegramMsg = {
    payload: {
        chatId: "8823676499",
        type: "message",
        content: "✅ Đã xác nhận an toàn. Báo động té ngã tự hủy."
    }
};
return [alarmMsg, telegramMsg];

global.set('fallLastAlertTime', 0);
global.set('gasLastAlertTime', 0);
global.set('dhtLastAlertTime_livingroom', 0);
global.set('dhtLastAlertTime_kitchen', 0);

// Firmware ESP32 hien subscribe home/esp32/alarm; ALARM_OFF se tat alarm tu xa.
msg.topic = "home/esp32/alarm";
msg.payload = "ALARM_OFF";
return msg;

var data = msg.payload || {};

var label = data.label || "Thuốc";
var scheduledTime = data.scheduledTime || "";

msg.payload = {
    chatId: "8823676499",
    type: "message",
    content:
        "💊 NHẮC UỐNG THUỐC\n" +
        "Chưa xác nhận: " + label +
        (scheduledTime ? "\nGiờ uống: " + scheduledTime : "") +
        "\nVui lòng kiểm tra và xác nhận trên hệ thống."
};

return msg;
